package main
import("fmt";"net/http";"net/http/httptest";"sync/atomic";"github.com/mmcdole/gofeed";feedjson "github.com/mmcdole/gofeed/json")
func main(){var n atomic.Int32;s:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){n.Add(1);w.Header().Set("Content-Type","application/feed+json");fmt.Fprint(w,`{"version":"https://jsonfeed.org/version/1.1","title":"catalog","next_url":"/p2","items":[{"id":"new-1","content_text":"one"}]}`)}));defer s.Close();p:=gofeed.NewParser();p.KeepOriginalFeed=true;f,e:=p.ParseURL(s.URL+"/p1");if e!=nil{panic(e)};raw,ok:=f.OriginalFeed().(*feedjson.Feed);if !ok||raw.NextURL!="/p2"||n.Load()!=1||len(f.Items)!=1{panic("unexpected feed")};fmt.Printf("existing ParseURL: requests=%d items=%d native-next=%s; no continuation fetched\n",n.Load(),len(f.Items),raw.NextURL)}
